import{_ as d,o as s,c as e,a0 as o}from"./chunks/framework.jwovEGr5.js";const a="/assets/menu_gui.D0aKR836.png",u=JSON.parse('{"title":"📜 /menu 選單大廳指南","description":"","frontmatter":{},"headers":[],"relativePath":"Mc-Menu-System.md","filePath":"Mc-Menu-System.md"}'),n={name:"Mc-Menu-System.md"};function r(c,t,i,p,l,h){return s(),e("div",null,[...t[0]||(t[0]=[o(`<h1 id="📜-menu-選單大廳指南" tabindex="-1">📜 /menu 選單大廳指南 <a class="header-anchor" href="#📜-menu-選單大廳指南" aria-label="Permalink to &quot;📜 /menu 選單大廳指南&quot;">​</a></h1><p>Craft-Core 提供了全方位視覺化的箱子選單大廳。您只需要輸入 <code>/menu</code> 即可開啟擁有 <strong>橫排 1~4 (Horizontal Rows)</strong> 完美橫向對齊分類的大廳介面，輕鬆體驗伺服器的所有功能。</p><hr><h2 id="🎮-開啟方式與指令" tabindex="-1">🎮 開啟方式與指令 <a class="header-anchor" href="#🎮-開啟方式與指令" aria-label="Permalink to &quot;🎮 開啟方式與指令&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 開啟選單大廳</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/menu</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 快捷別名</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/m</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/cd</span></span></code></pre></div><hr><h2 id="🧭-橫排-horizontal-rows-視覺化架構" tabindex="-1">🧭 橫排 (Horizontal Rows) 視覺化架構 <a class="header-anchor" href="#🧭-橫排-horizontal-rows-視覺化架構" aria-label="Permalink to &quot;🧭 橫排 (Horizontal Rows) 視覺化架構&quot;">​</a></h2><p>開啟選單大廳後，所有功能圖示依據性質精確歸類於 <strong>4 個橫排 (Row 2, Row 3, Row 4, Row 5)</strong> 中：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>【橫排 1 - 核心經濟與交易】 🏪 商店管理系統 | 📜 銀行支票中心 | 📦 虛擬快遞箱 | 🗑️ 隨身垃圾桶</span></span>
<span class="line"><span>【橫排 2 - 傳送與領地保全】 🧭 傳送與家園   | 🛡️ 領地與密碼箱 | 🤝 玩家 TPA 傳送 | ⚔️ PvP 戰鬥切換</span></span>
<span class="line"><span>【橫排 3 - 社群與福利活動】 🎰 福利中心     | ⚔️ 每日任務懸賞 | 🏆 全服排行榜   | 💬 Discord 社群</span></span>
<span class="line"><span>【橫排 4 - 工具與機器控制】 🤖 假人控制台   | 🏭 機器認證申請 | 🛠️ 管理員控制台 | 📖 說明指南 (/help)</span></span></code></pre></div><p><img src="`+a+'" alt="Craft-Core 橫排選單大廳"></p><hr><h2 id="💡-選單功能介紹" tabindex="-1">💡 選單功能介紹 <a class="header-anchor" href="#💡-選單功能介紹" aria-label="Permalink to &quot;💡 選單功能介紹&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能橫排</th><th>選單圖示</th><th>選單名稱</th><th>點擊效果說明</th></tr></thead><tbody><tr><td><strong>橫排 1</strong></td><td>🏪</td><td><code>商店管理系統</code></td><td>點擊開啟 <code>/shop</code>，瀏覽全服商店市場與提領個人擺攤收益。</td></tr><tr><td><strong>橫排 1</strong></td><td>📜</td><td><code>銀行支票中心</code></td><td>點擊開啟 <code>/check</code> 支票開立中心，開立實體可交易紙張支票。</td></tr><tr><td><strong>橫排 1</strong></td><td>📦</td><td><code>虛擬快遞箱</code></td><td>開啟寄件箱與收件箱，向線上或離線玩家寄送物品 (<code>/express</code>)。</td></tr><tr><td><strong>橫排 1</strong></td><td>🗑️</td><td><code>隨身垃圾桶</code></td><td>開啟 10 秒自動銷毀隨身垃圾桶 (<code>/wastebin</code>)。</td></tr><tr><td><strong>橫排 2</strong></td><td>🧭</td><td><code>傳送與家園</code></td><td>列出個人所有家點、公共地標、一鍵隨機傳送 (<code>/rtp</code>) 與死亡點 (<code>/back</code>)。</td></tr><tr><td><strong>橫排 2</strong></td><td>🛡️</td><td><code>領地與密碼箱</code></td><td>管理個人領地、獲取圈地木斧以及箱子密碼鎖設定 (<code>/padlock</code>)。</td></tr><tr><td><strong>橫排 2</strong></td><td>🤝</td><td><code>玩家傳送請求</code></td><td>點擊開啟線上玩家頭顱列表，一鍵發送對點傳送請求 (<code>/tpa</code>)。</td></tr><tr><td><strong>橫排 2</strong></td><td>⚔️</td><td><code>PvP 戰鬥狀態</code></td><td>一鍵切換個人 PvP 狀態（預設和平保護，免受他人攻擊）。</td></tr><tr><td><strong>橫排 3</strong></td><td>🎰</td><td><code>福利中心</code></td><td>每日簽到領獎、在線時數兌換鑰匙與 9x3 幸運轉盤抽獎。</td></tr><tr><td><strong>橫排 3</strong></td><td>⚔️</td><td><code>任務與懸賞</code></td><td>查看每日擊殺挖掘任務、全服共同大目標與野外藏寶圖線索。</td></tr><tr><td><strong>橫排 3</strong></td><td>🏆</td><td><code>全服排行榜</code></td><td>查看全服財富 Top 10、抽獎鑰匙 Top 10 與連續簽到排行榜。</td></tr><tr><td><strong>橫排 3</strong></td><td>💬</td><td><code>Discord 社群</code></td><td>獲取官方 Discord 邀請連結或生成 6 位數帳號綁定碼 (<code>/discord link</code>)。</td></tr><tr><td><strong>橫排 4</strong></td><td>🤖</td><td><code>假人控制台</code></td><td>開啟假人選單，一鍵召喚/解散假人、切換掛機動作與查看背包。</td></tr><tr><td><strong>橫排 4</strong></td><td>🏭</td><td><code>機器認證</code></td><td>站在自動化機器領地內點擊一鍵提交審核申請 (<code>/machine apply</code>)。</td></tr><tr><td><strong>橫排 4</strong></td><td>🛠️</td><td><code>管理員控制台</code></td><td>(OP 專屬) 全服玩家背包監看、機器審核與地圖備份。</td></tr><tr><td><strong>橫排 4</strong></td><td>📖</td><td><code>伺服器指南</code></td><td>聊天欄傳送高質感點擊連結前往線上說明文件 (<code>https://docs.craft-core.xyz</code>)。</td></tr></tbody></table>',13)])])}const m=d(n,[["render",r]]);export{u as __pageData,m as default};
